# Updated transform to handle single-separator case properly
def transform_v3(grid):
    if not grid:
        return grid

    uniform_values = {}
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            val = row[0]
            uniform_values.setdefault(val, []).append((i, row))

    if not uniform_values:
        return grid
    if len(uniform_values) == 1:
        # Only one uniform value, use all rows as content
        return grid

    most_common_val = max(uniform_values.keys(), key=lambda k: len(uniform_values[k]))
    separator_val = [k for k in uniform_values.keys() if k != most_common_val][0]

    # Find separators (first and second occurrence)
    separators = [r for r, _ in uniform_values[separator_val]]

    if not separators:
        return grid

    if len(separators) < 2:
        # Only one separator - use rows BEFORE it as content
        content_rows = grid[0:separators[0]]
    else:
        # Use rows between first and second separator
        content_rows = grid[separators[0]+1:separators[1]]

    content_height = len(content_rows)

    output = []
    for i in range(len(grid)):
        pattern_idx = i % (content_height + 1)
        if pattern_idx < content_height:
            output.append(content_rows[pattern_idx])
        else:
            output.append([separator_val] * len(content_rows[0]))

    return output

